'use strict';
const D=JSON.parse(document.getElementById('atlas-data').textContent),E=D.entries,SOURCES=new Map(D.sources.map(s=>[s.id,s]));
const LABELS={endpoint:'Endpoints',parameter:'Paramètres',event:'Événements',header:'Headers',capability:'Capacités',tool:'Outils',runtime:'Runtime',overview:'Vue d’ensemble',architecture:'Architecture',schemas:'Laboratoire de schémas',roadmap:'Feuille de route',sources:'Sources & versions',experiments:'Validation'};
const MAP={identical:['Identique dans le code','green'],candidate:['Relais candidat','green'],translation:['Adaptation','blue'],superset:['Superset','purple'],codex_only:['Extension Codex','purple'],runtime:['Runtime requis','blue'],unknown:['À vérifier','amber']};
const LOC={BACKEND_NATIVE:['Backend natif','green'],RUNTIME_LOCAL:['Runtime local','blue'],HYBRID:['Hybride','purple'],UNKNOWN:['Non établi','amber']};
const CONF={HIGH:'Source solide',MEDIUM:'À recouper',UNKNOWN:'Non établi'};
const state={route:'overview',category:null,query:'',family:'',mapping:'',location:'',lot:'',confidence:'',page:1,detailTab:'mapping',schemaDoc:null,schemaName:'',schemaPointer:'',schemaResult:null,schemaTab:'raw',schemaBefore:null,schemaFiltered:'',archTab:'wire'};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const paths={atlas:'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z M10 7h4 M7 10v4 M17 10v4 M10 17h4',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',endpoint:'M5 7h14 M15 3l4 4-4 4 M19 17H5 M9 13l-4 4 4 4',parameter:'M8 4H5v16h3 M16 4h3v16h-3 M10 8h4 M10 12h4 M10 16h4',event:'M3 12h4l3-8 4 16 3-8h4',header:'M4 5h16v14H4z M4 9h16 M8 13h3 M8 16h7',capability:'M12 3l8 4v10l-8 4-8-4V7z M4 7l8 5 8-5 M12 12v9',tool:'M14 5a5 5 0 0 0-6 6l-5 5 5 5 5-5a5 5 0 0 0 6-6l-4 2-3-3z',runtime:'M4 4h16v12H4z M8 20h8 M12 16v4 M7 8l3 2-3 2 M12 12h4',architecture:'M9 3h6v5H9z M3 16h6v5H3z M15 16h6v5h-6z M12 8v4 M6 16v-4h12v4',schemas:'M8 4l-5 8 5 8 M16 4l5 8-5 8 M14 4l-4 16',roadmap:'M5 3v18 M5 4h12l-3 4 3 4H5 M5 20h14',sources:'M6 3h10l4 4v14H6z M16 3v5h4 M9 12h8 M9 16h6',experiments:'M9 3h6 M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3 M7 16h10',search:'M15 15l6 6 M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',external:'M14 3h7v7 M21 3l-11 11 M10 3H4v17h17v-6',sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1 M17 12a5 5 0 1 0-10 0 5 5 0 0 0 10 0',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',system:'M3 4h18v13H3z M8 21h8 M12 17v4',menu:'M4 6h16 M4 12h16 M4 18h16',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',copy:'M9 9h12v12H9z M15 9V3H3v12h6',check:'M4 12l5 5L20 6',info:'M12 11v6 M12 7v1 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',back:'M20 12H4 M10 6l-6 6 6 6',close:'M5 5l14 14 M19 5L5 19',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',branch:'M6 3v14a3 3 0 0 0 6 0V9a3 3 0 0 1 6 0v12'};
function icon(n){return`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;}
function badge(v,lookup=MAP){const [text,cls]=lookup[v]||[v,''];return`<span class="pill ${cls}">${esc(text)}</span>`;}
function pill(t,c=''){return`<span class="pill ${c}">${esc(t)}</span>`;}
function count(cat){return E.filter(e=>e.category===cat).length;}
function sourceLink(id,label){const s=SOURCES.get(id);return s?`<a class="link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label||s.title)} ↗</a>`:'<span class="muted">Source non renseignée</span>';}
function codebox(title,text,lang='JSON'){const id='code-'+Math.random().toString(36).slice(2);return`<div class="codebox"><div class="codehead"><span>${esc(title)} · ${esc(lang)}</span><button class="btn ghost" data-copy="${id}" aria-label="Copier le code">${icon('copy')}</button></div><pre id="${id}">${esc(text)}</pre></div>`;}
function scores(n){return`<span class="score" aria-label="${n} sur 5">${Array.from({length:5},(_,i)=>`<i class="${i<n?'filled':''}"></i>`).join('')}</span>`;}
function footer(){return`<footer class="footer"><span>Codex Contract Atlas · audit du ${esc(D.meta.date)} · v0.1</span><span><a href="#sources">Provenance</a> &nbsp; / &nbsp; <a href="#experiments">Limites & validation</a> &nbsp; / &nbsp; <button class="btn ghost" data-export="json">JSON ${icon('download')}</button></span></footer>`;}
function heading(kicker,title,desc,actions=''){return`<header class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</header>`;}
function nav(){const groups=[['Explorer',[['overview','Vue d’ensemble'],['endpoint','Endpoints'],['parameter','Paramètres'],['event','Événements'],['header','Headers']]],['Comprendre',[['capability','Capacités'],['tool','Outils & extensions'],['runtime','Runtime Codex'],['architecture','Architecture cible']]],['Construire',[['schemas','Schémas & diffs'],['roadmap','Feuille de route'],['sources','Sources & versions'],['experiments','Tests & inconnues']]]];
 $('#sidebar').innerHTML=`<a class="brand" href="#overview"><span class="brand-mark">${icon('atlas')}</span><span>Contract Atlas<small>OpenAI × Codex</small></span></a>${groups.map(([g,items])=>`<div class="nav-group"><div class="nav-label">${g}</div>${items.map(([id,text])=>`<a class="nav-link" href="#${['endpoint','parameter','event','header','capability','tool','runtime'].includes(id)?'explore/':''}${id}" data-nav="${id}">${icon(id)}<span>${text}</span>${count(id)?`<span class="nav-count">${count(id)}</span>`:''}</a>`).join('')}</div>`).join('')}<div class="sidebar-foot"><div><span class="pill green"><i class="dot"></i>Audit de sources</span><p>Contrats observés ≠ capacités garanties.<br>Aucune requête authentifiée.</p></div></div>`;
 $('#topbar').innerHTML=`<button class="mobile-menu" id="menu-btn" aria-label="Ouvrir le menu" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb" id="breadcrumb">Documentation <span>/ Vue d’ensemble</span></div><button class="search-btn" data-action="search" aria-label="Rechercher dans l’atlas">${icon('search')}<span>Rechercher dans l’atlas…</span><kbd>⌘ K</kbd></button><button class="theme-btn" id="theme-btn" aria-label="Changer de thème"></button><button class="btn" data-export="json">Exporter ${icon('download')}</button>`;
}
function diagram(){return`<div class="diagram"><div class="diagram-title">${icon('architecture')}Architecture cible · proposition</div><div class="flow-node">Client OpenAI-compatible<small>HTTP · SSE · WebSocket</small></div><div class="flow-line"></div><div class="flow-node accent">Façade minimale<small>auth · routage · adaptations explicites</small></div><div class="flow-line"></div><div class="flow-branch"><div><div class="flow-node">Backend natif<small>Responses · Images · Realtime</small></div></div><div><div class="flow-node">Runtime Codex<small>Outils · agents · permissions</small></div></div></div><div class="flow-foot"><span>Préserver les échanges bruts</span><span>Réutiliser le moteur officiel</span></div></div>`;}
function overview(){const finds=[['images','Images : une voie directe','Les clients Images dédiés permettent de séparer génération et édition de la boucle agentique. L’API publique accepte aussi l’édition JSON.','ep-images-edits','endpoint'],['sse','Le parseur n’est pas le protocole','Le parseur SSE interne ignore certains événements. Un relais sans perte doit conserver le flux brut, pas le reconstruire depuis ses objets.','ev-response.function_call_arguments.delta','event'],['rtcore','Une voix, plusieurs chemins','WebSocket direct, WebRTC et sideband n’ont pas la même chaîne d’authentification. Chaque transport nécessite sa propre validation.','Realtime','capability'],['app','Le runtime reste indispensable','Shell, permissions et orchestration locale ne se récupèrent pas en relayant une requête au backend. Réutiliser Codex évite de les réécrire.','runtime','runtime']];
 return`<div class="audit-strip"><i class="dot"></i><span>AUDIT DE SOURCES</span><span>·</span><span>19 septembre 2026</span><a class="right link" href="#experiments">Périmètre & limites ${icon('arrow')}</a></div><section class="hero"><div><div class="eyebrow">OpenAI-compatible. Codex au plus près.</div><h1>Le contrat,<br>sans la <em>boîte noire.</em></h1><p>Explorer ce qui vient du backend, ce qui appartient au runtime et ce qu’il faut adapter — sans sacrifier les capacités ni masquer les inconnues.</p><div class="actions"><a class="btn primary" href="#explore/endpoint">Explorer les contrats ${icon('arrow')}</a><a class="btn" href="#architecture">Voir l’architecture</a></div></div>${diagram()}</section><div class="stats"><a href="#explore/parameter" class="stat"><div class="stat-number">${E.length}</div><div class="stat-label">Fiches de mapping</div></a><a href="#explore/endpoint" class="stat"><div class="stat-number">${count('endpoint')}</div><div class="stat-label">Routes inventoriées</div></a><a href="#sources" class="stat"><div class="stat-number">${D.sources.length}</div><div class="stat-label">Sources référencées</div></a><a href="#experiments" class="stat"><div class="stat-number">0</div><div class="stat-label">Tests backend exécutés</div></a></div><div class="notice"><strong>Ce que ces chiffres mesurent :</strong> un inventaire éditorial sourcé, pas un pourcentage de compatibilité. Sources <code>main</code> non figées ; les capacités dépendent encore du compte et du modèle. <a href="#sources">Examiner les preuves →</a></div><div class="section-head"><h2>Ce qui change le design</h2><a class="link small" href="#roadmap">Passer à l’implémentation →</a></div><div class="grid-2">${finds.map(([sid,title,txt,target,cat])=>{let e=E.find(x=>x.id===target);let href=e?'#entry/'+encodeURIComponent(e.id):target==='runtime'?'#explore/runtime':'#explore/capability?family=Realtime';return`<div class="card"><div class="card-head">${icon(cat)}<h3>${title}</h3></div><p>${txt}</p><div class="small muted" style="margin-top:10px">${sourceLink(sid,'Preuve dans la source')}${sid==='images'?' · '+sourceLink('openapi','Contrat public'):''}</div><a class="read-more" href="${href}">Examiner le mapping ${icon('arrow')}</a></div>`;}).join('')}</div><div class="section-head"><h2>Où les capacités s’exécutent</h2><a class="link small" href="#explore/capability">${count('capability')} capacités →</a></div><div class="feature-grid">${Object.entries(LOC).map(([key,[label,cls]])=>`<a class="feature-tile" href="#explore/capability?location=${key}"><div class="tags">${pill(label,cls)}<span class="feature-count">${E.filter(e=>e.category==='capability'&&e.executionLocation===key).length}</span></div><h3>${key==='BACKEND_NATIVE'?'Relayer le contrat':key==='RUNTIME_LOCAL'?'Conserver le moteur':key==='HYBRID'?'Respecter la frontière':'Tester avant d’annoncer'}</h3><p>${key==='BACKEND_NATIVE'?'Une piste backend, pas une garantie d’accès.':key==='RUNTIME_LOCAL'?'Les effets sont exécutés sur l’hôte.':key==='HYBRID'?'Le backend et l’hôte coopèrent.':'Absence de preuve ≠ absence de capacité.'}</p></a>`).join('')}</div><div class="section-head"><h2>Du mapping à la preuve</h2></div><div class="steps"><a href="#schemas" class="step"><div class="eyebrow">01 / Contrat public</div><h3>Résoudre les schémas</h3><p>Importer OpenAPI, suivre les références et garder les branches <code>allOf</code>, <code>oneOf</code> et <code>anyOf</code>.</p></a><a href="#sources" class="step"><div class="eyebrow">02 / Contrat observé</div><h3>Retrouver l’origine</h3><p>Pointer le sérialiseur, le type, le transport et les transformations. Le schéma généré ne suffit pas toujours.</p></a><a href="#experiments" class="step"><div class="eyebrow">03 / Comportement réel</div><h3>Valider avec le compte</h3><p>Comparer appels directs et proxifiés. Tester erreurs, streaming, état, quotas et isolation entre comptes.</p></a></div>${footer()}`;
}
function resetFilters(){state.query='';state.family='';state.mapping='';state.location='';state.lot='';state.confidence='';state.page=1;}
function baseRows(){return E.filter(e=>state.category==='runtime'?['RUNTIME_LOCAL','HYBRID'].includes(e.executionLocation):!state.category||e.category===state.category);}
function searchText(e){return norm([e.name,e.id,e.family,e.openai?.name,e.openai?.pointer,e.codex?.name,e.codex?.symbol,e.notes.join(' '),(e.codex?.originChain||[]).join(' '),(e.openai?.originChain||[]).join(' '),e.transformation].join(' '));}
function filtered(){const q=norm(state.query);return baseRows().filter(e=>(!q||searchText(e).includes(q))&&(!state.family||e.family===state.family)&&(!state.mapping||e.mapping===state.mapping)&&(!state.location||e.executionLocation===state.location)&&(state.lot===''||e.lot===+state.lot)&&(!state.confidence||e.confidence===state.confidence));}
function options(values,selected,placeholder){return`<option value="">${placeholder}</option>`+values.map(v=>{const[key,label]=Array.isArray(v)?v:[v,v];return`<option value="${esc(key)}" ${selected===String(key)?'selected':''}>${esc(label)}</option>`;}).join('');}
function explorer(){const cat=state.category,title=LABELS[cat]||'Tous les contrats';const descriptions={endpoint:'De la route publique au chemin upstream : transport, authentification, formes de payload et points non établis.',parameter:'Comparer les champs publics et Codex, leurs types, leur provenance et les adaptations nécessaires.',event:'Séparer le flux réseau brut des événements transformés ou ignorés par le parseur du runtime.',header:'Distinguer authentification, corrélation, continuité et metadata. Aucun forwarding aveugle des secrets.',capability:'Ce que Codex sait exposer, où cela s’exécute et ce qui reste à valider sur un compte réel.',tool:'L’appel produit par le modèle et l’exécution de l’outil ne sont pas la même chose.',runtime:'Surfaces locales et hybrides : réutiliser le runtime officiel lorsque le backend ne suffit pas.'};
 return`${heading('Explorateur / '+title,esc(title),descriptions[cat]||'Inventaire sourcé.',`<button class="btn" data-export="filtered-json">JSON ${icon('download')}</button><button class="btn" data-export="filtered-csv">CSV ${icon('download')}</button>`)}<div class="filterbar"><input class="field" id="filter-query" placeholder="Rechercher un champ, une route, un symbole…" value="${esc(state.query)}" aria-label="Rechercher dans les fiches"><select class="field" data-filter="family" aria-label="Famille">${options([...new Set(baseRows().map(e=>e.family))].sort(),state.family,'Toutes les familles')}</select><select class="field" data-filter="mapping" aria-label="Type de mapping">${options(Object.entries(MAP).map(([k,v])=>[k,v[0]]),state.mapping,'Tous les mappings')}</select><select class="field" data-filter="location" aria-label="Lieu d’exécution">${options(Object.entries(LOC).map(([k,v])=>[k,v[0]]),state.location,'Toutes les couches')}</select><select class="field" data-filter="lot" aria-label="Lot">${options(D.lots.map(l=>[l.id,'Lot '+l.id+' · '+l.title]),state.lot,'Tous les lots')}</select><button class="btn ghost" data-action="reset-filters" title="Réinitialiser les filtres" aria-label="Réinitialiser les filtres">${icon('close')}</button></div><div id="results"></div><div class="legend"><span><strong>Relais candidat</strong> = correspondance à tester, pas compatibilité validée.</span><span><strong>Source solide</strong> = preuve dans le code, pas succès backend.</span></div>${footer()}`;
}
function renderResults(){if(!$('#results'))return;const rows=filtered(),size=30,pages=Math.max(1,Math.ceil(rows.length/size));state.page=Math.min(state.page,pages);const pageRows=rows.slice((state.page-1)*size,state.page*size);$('#results').innerHTML=`<div class="results-meta"><span><strong>${rows.length}</strong> fiches ${rows.length!==baseRows().length?'sur '+baseRows().length:''}</span><span>Preuve source ≠ test authentifié</span></div><div class="table-wrap">${rows.length?`<table class="data-table"><thead><tr><th>Contrat / champ</th><th>Mapping</th><th class="hide-mobile">Exécution</th><th class="hide-mobile">Transport</th><th class="hide-mobile">Lot</th><th class="hide-mobile">Preuve</th></tr></thead><tbody>${pageRows.map(e=>`<tr data-entry="${esc(e.id)}"><td><a class="name" href="#entry/${encodeURIComponent(e.id)}">${esc(e.name)}</a><div class="row-sub">${esc(e.family)}${e.parserBehavior?' · parseur : '+esc(e.parserBehavior):''}</div></td><td>${badge(e.mapping)}</td><td class="hide-mobile">${badge(e.executionLocation,LOC)}</td><td class="hide-mobile"><span class="small muted">${esc(e.transport.join(' / '))}</span></td><td class="hide-mobile"><a class="link small" href="#roadmap/lot-${e.lot}">${String(e.lot).padStart(2,'0')}</a></td><td class="hide-mobile"><span class="small muted">${esc(CONF[e.confidence]||e.confidence)}</span></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('search')}Aucun résultat avec ces filtres.<br><button class="btn ghost link" data-action="reset-filters">Réinitialiser</button></div>`}</div><div class="pagination"><span>${rows.length?((state.page-1)*size+1)+'–'+Math.min(state.page*size,rows.length):'0'} / ${rows.length} fiches</span><div class="actions"><button class="btn" data-page="${state.page-1}" ${state.page===1?'disabled':''}>← Précédent</button><span style="padding:8px 3px">${state.page} / ${pages}</span><button class="btn" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>Suivant →</button></div></div>`;}
function contractCard(side,name){if(!side)return`<section class="contract"><div class="contract-header">${name}</div><div class="contract-body"><p class="small muted">Correspondance non établie dans cette fiche.</p><p class="small muted" style="margin-top:8px">Ce n’est pas une preuve d’absence dans l’API.</p></div></section>`;return`<section class="contract"><div class="contract-header"><span>${name}</span>${pill(name==='OpenAI public'?'Public':'Code source',name==='OpenAI public'?'blue':'green')}</div><div class="contract-body"><div class="mono">${esc(side.name)}</div><dl class="spec-list"><dt>Type</dt><dd>${esc(side.type||'Non résolu ici')}</dd><dt>Obligatoire</dt><dd>${side.required===true?'Oui dans cette branche':side.required===false?'Non dans cette branche':'Non établi'}</dd><dt>Nullable</dt><dd>${side.nullable===true?'Oui':side.nullable===false?'Non':'Non établi'}</dd>${side.values?`<dt>Valeurs</dt><dd>${esc(Array.isArray(side.values)?side.values.join(' · '):JSON.stringify(side.values))}</dd>`:''}<dt>Symbole</dt><dd>${esc(side.symbol||side.pointer||'Non renseigné')}</dd></dl><div class="eyebrow" style="margin-top:20px">Chaîne d’origine</div><ol class="provenance">${(side.originChain||[]).map(p=>`<li>${esc(p)}</li>`).join('')}</ol><div class="small" style="margin-top:13px">${sourceLink(side.sourceId)}</div></div></section>`;}
function entry(id){const e=E.find(x=>x.id===id);if(!e)return heading('Fiche introuvable','Référence inconnue','Cette référence ne fait pas partie du jeu de données.')+`<a class="btn" href="#overview">Accueil</a>`;state.currentEntry=e;const related=E.filter(x=>x.id!==id&&x.family===e.family&&(x.category!==e.category||e.category==='parameter')).slice(0,6);return`<a class="back" href="#explore/${e.category}">${icon('back')}Retour à ${LABELS[e.category].toLowerCase()}</a>${heading(e.family+' / '+LABELS[e.category],`<span class="mono" style="font-size:.79em">${esc(e.name)}</span>`,`${e.notes.length?esc(e.notes[0]):esc(e.transformation)}`,`<button class="btn" data-action="copy-entry-link">Lien ${icon('copy')}</button><button class="btn" data-export="entry">JSON ${icon('download')}</button>`)}<div class="tags">${badge(e.mapping)}${badge(e.executionLocation,LOC)}${e.transport.map(t=>pill(t)).join('')}${pill(CONF[e.confidence]||e.confidence)}${pill('Non testé en direct','amber')}</div><div class="tabs"><button class="tab ${state.detailTab==='mapping'?'active':''}" data-detail-tab="mapping">Mapping & provenance</button><button class="tab ${state.detailTab==='json'?'active':''}" data-detail-tab="json">Fiche JSON</button><button class="tab ${state.detailTab==='tests'?'active':''}" data-detail-tab="tests">Validation</button></div><div class="detail-layout"><article id="entry-content">${entryBody(e)}</article><aside class="detail-aside"><div class="card"><h4>Repères d’implémentation</h4><div class="fact"><small>Feuille de route</small><a class="link" href="#roadmap/lot-${e.lot}">Lot ${e.lot} · ${esc(D.lots.find(l=>l.id===e.lot)?.title||'')}</a></div><div class="fact"><small>Recherche · estimation</small>${scores(e.researchComplexity)}</div><div class="fact"><small>Implémentation · estimation</small>${scores(e.implementationComplexity)}</div><div class="fact"><small>Risque de perte</small><span>${esc({high:'Élevé',medium:'Moyen',low:'Faible'}[e.lossRisk]||e.lossRisk)}</span></div><div class="fact"><small>Maintenance</small><span>${esc({high:'Élevée',medium:'Modérée',low:'Faible'}[e.maintenanceRisk]||e.maintenanceRisk)}</span></div><div class="fact"><small>Révision des sources</small><span><code>main</code> non figé</span></div><p class="small muted" style="margin-top:13px">Échelles de 1 à 5 : estimations de cet audit, pas durées mesurées.</p></div><div class="detail-section"><h4>Dans la même famille</h4>${related.map(r=>`<a href="#entry/${encodeURIComponent(r.id)}" class="nav-link" style="font-size:10px;padding:8px 0;overflow-wrap:anywhere">${esc(r.name)} ${icon('chevron')}</a>`).join('')}</div></aside></div>${footer()}`;}
function entryBody(e){if(state.detailTab==='json')return`<div class="notice" style="margin-bottom:15px">JSON de la <strong>fiche d’audit</strong>. Il ne s’agit ni du schéma OpenAPI brut complet, ni d’une capture réseau.</div>${codebox(e.id,JSON.stringify(e,null,2))}`;if(state.detailTab==='tests')return`<div class="notice amber">Ces tests sont des critères d’acceptation proposés. Aucun résultat d’appel authentifié n’est disponible.</div><section class="detail-section"><h2>À vérifier pour cette fiche</h2>${e.tests.map((t,i)=>`<div class="layer-line"><h4>Test ${i+1}</h4><p>${esc(t)}</p></div>`).join('')}</section><section class="detail-section"><h2>Expériences du lot ${e.lot}</h2>${D.experiments.filter(x=>x.lot===e.lot||x.lot===0).map(x=>`<div class="card" style="margin-bottom:10px"><div class="tags">${pill(x.id)}${pill('Non exécuté','amber')}</div><h3 style="margin-top:10px">${esc(x.title)}</h3><p>${esc(x.procedure)}</p></div>`).join('')}</section>`;
 return`${e.endpoint?`<div class="codebox"><div class="codehead"><span>Route publique → surface Codex</span>${pill(e.endpoint.method)}</div><pre>${esc(e.endpoint.publicPath?e.endpoint.method+' /v1'+e.endpoint.publicPath:'Pas d’équivalent public établi')}\n       ↓\n${esc(e.endpoint.upstream||'Route backend non identifiée')}</pre></div>`:''}<div class="contract-pair">${contractCard(e.openai,'OpenAI public')}${contractCard(e.codex,'Codex')}</div>${e.requirednessNote?`<div class="notice" style="margin-top:15px">${esc(e.requirednessNote)}</div>`:''}<section class="detail-section"><h2>Comment réaliser ce mapping</h2><p>${esc(e.transformation)}</p>${e.notes.map(n=>`<div class="note-line">${icon('info')}<span>${esc(n)}</span></div>`).join('')}${e.parserBehavior?`<div class="notice amber">Parseur Codex : <strong>${esc(e.parserBehavior)}</strong>. Ce comportement ne décrit pas ce que le backend a émis, mais ce que le client en a conservé.</div>`:''}</section><section class="detail-section"><h2>Conditions & frontières</h2><div class="card"><dl class="spec-list" style="margin-top:0"><dt>Auth</dt><dd>${esc(e.authRequirements)}</dd><dt>Modèle</dt><dd>${esc(e.modelRequirements)}</dd>${e.producer?`<dt>Producteur</dt><dd>${esc(e.producer)}</dd><dt>Consommateur</dt><dd>${esc(e.consumer)}</dd><dt>Rôle</dt><dd>${esc(e.role)}</dd>`:''}<dt>Preuve</dt><dd>${esc(e.evidenceBasis)} · ${esc(CONF[e.confidence]||e.confidence)}</dd></dl></div></section><section class="detail-section"><h2>Critère d’acceptation</h2>${e.tests.map(t=>`<div class="note-line">${icon('experiments')}<span>${esc(t)}</span></div>`).join('')}<div class="small muted" style="margin-top:12px">Résultat : non exécuté sur le backend. Préserver les erreurs et refus réels plutôt que simuler une compatibilité.</div></section>`;
}
function architecture(){return`${heading('Design / Architecture','Le minimum de traduction.<br>Pas le minimum de fonctionnalités.','Proposition d’architecture : une façade standard pour les contrats compatibles, une voie native explicite pour les contrôles Codex sans équivalent.')}<div class="grid-2" style="align-items:center">${diagram()}<div><div class="layer-line"><h4>1. Un chemin de données opaque</h4><p>Relayer les bodies, événements et champs inconnus du sous-ensemble validé. Ne pas les reconstruire à partir de types Codex incomplets.</p></div><div class="layer-line"><h4>2. Des adaptations localisées</h4><p>Conversion uniquement pour une différence démontrée : payload, protocole, résultat non streamé. Chaque changement possède un test.</p></div><div class="layer-line"><h4>3. Un runtime officiel optionnel</h4><p>Préserver outils, sandbox, approvals et agents sans réimplémenter leur moteur. Ses RPC restent distincts de la Responses API.</p></div></div></div><div class="arch-grid"><section class="arch-pane"><div class="eyebrow">Chemin A / Backend</div><h2>Le contrat, au plus près du réseau</h2><div class="mono">Client → façade → backend autorisé<br>Réponse upstream → client</div><p>Responses HTTP/SSE/WS, Images, catalogue et Realtime passent par leurs transports et authentifications propres. Le relais ne garantit pas que le compte ait accès à chaque surface.</p><div class="tags" style="margin-top:15px">${pill('Bodies bruts','green')}${pill('Événements préservés','green')}${pill('Auth par route')}</div><div class="small" style="margin-top:14px">${sourceLink('common','Contrat Responses')} · ${sourceLink('sse','Parseur SSE')}</div></section><section class="arch-pane"><div class="eyebrow">Chemin B / Runtime</div><h2>Le moteur, plutôt qu’une imitation</h2><div class="mono">Contrôles Codex → App Server<br>Tools / sessions / permissions → hôte</div><p>La façade peut intégrer le runtime, mais ne doit pas annoncer que chaque RPC est standard OpenAI. Les opérations sans équivalent conservent un espace de noms distinct.</p><div class="tags" style="margin-top:15px">${pill('App Server','blue')}${pill('JSON-RPC','blue')}${pill('Isolation par session')}</div><div class="small" style="margin-top:14px">${sourceLink('app','Protocole App Server')} · ${sourceLink('spawn','Orchestration locale')}</div></section></div><div class="section-head"><h2>Les invariants du relais</h2></div><div class="grid-2"><div class="card"><div class="card-head">${icon('event')}<h3>Préserver sans normaliser</h3></div><p>Champs inconnus, items chiffrés, séquence des événements, statuts et erreurs doivent survivre au transport. Le parseur métier n’est pas un intermédiaire obligatoire.</p></div><div class="card"><div class="card-head">${icon('lock')}<h3>Ne pas tout transmettre</h3></div><p>Credentials, cookies, headers hop-by-hop et redirections demandent une politique stricte. Les réponses d’un compte ne doivent jamais servir à un autre.</p></div><div class="card"><div class="card-head">${icon('branch')}<h3>Maintenir la continuité</h3></div><p>Ne pas changer silencieusement de compte pendant une session. Conserver les identifiants, l’état opaque et l’affinité ; tester reconnexions et interruptions.</p></div><div class="card"><div class="card-head">${icon('parameter')}<h3>Limiter les promesses</h3></div><p>Un modèle dans un catalogue, un champ Rust ou un feature flag ne prouvent pas l’activation. Les capacités affichées doivent refléter les tests du compte.</p></div></div><div class="section-head"><h2>La place de Bifrost</h2></div><div class="notice"><strong>Intégration proposée, non testée :</strong> Bifrost peut rester le point d’entrée de routage. Le chemin natif Responses doit éviter les conversions Chat Completions inutiles. Vérifier séparément que la version déployée préserve les champs, headers et transports nécessaires ; un provider HTTP ne suffit pas à prouver le support WS ou Realtime.</div><div class="section-head"><h2>Ce qui ne sera pas simulé</h2></div><p class="muted small">Pas de fausse attestation, pas de contournement d’entitlement, pas de routage vers des hôtes arbitraires, pas de réussite synthétique lorsqu’une route est indisponible. Une adaptation explicitement limitée vaut mieux qu’une compatibilité silencieusement dégradée.</p>${footer()}`;}
function roadmap(){const ordered=[0,2,1,3,4,5,6,7,8,9,10];return`${heading('Construire / Feuille de route','Livrer par lots vérifiables.','Ordre proposé : fiabiliser le socle et les capacités, livrer Responses, puis étendre les transports, les médias et le runtime. Les numéros conservent le découpage du cahier des charges.')}<div class="notice"><strong>Lecture des estimations :</strong> recherche et implémentation sont notées de 1 à 5 par cet audit. Elles ne sont pas des délais en jours. Une dépendance non vérifiée bloque la promesse de compatibilité, pas nécessairement le prototypage.</div><div class="roadmap">${ordered.map(id=>{const l=D.lots.find(x=>x.id===id);return`<section class="lot" id="lot-${id}"><div class="lot-index">${String(id).padStart(2,'0')}</div><div class="lot-body"><div class="lot-top"><div><h3>${esc(l.title)}</h3><p>${esc(l.value)}</p></div>${pill(l.entryIds.length+' fiches')}</div><div class="tags">${l.dependencies.length?l.dependencies.map(d=>`<a class="pill" href="#roadmap/lot-${d}">Dépend du lot ${d}</a>`).join(''):pill('Point de départ','green')}${pill('Risque '+({medium:'modéré',high:'élevé',low:'faible'}[l.risk]||l.risk),l.risk==='high'?'amber':'')}</div><div class="riskline"><span>Recherche ${scores(l.researchComplexity)}</span><span>Implémentation ${scores(l.implementationComplexity)}</span></div><details><summary>Contrats, expériences et critères de sortie</summary><div><p>${esc(l.researchRemaining)}</p>${l.experiments.map(xid=>{const x=D.experiments.find(y=>y.id===xid);return x?`<div class="note-line">${icon('experiments')}<span><strong>${esc(x.id)} · ${esc(x.title)}</strong><br>${esc(x.procedure)}</span></div>`:'';}).join('')}<div class="tags">${l.entryIds.slice(0,8).map(eid=>{const e=E.find(x=>x.id===eid);return`<a href="#entry/${encodeURIComponent(eid)}" class="pill">${esc(e?.name||eid)}</a>`;}).join('')}</div><a class="read-more link small" href="#explore/all?lot=${id}" style="display:inline-block;margin-top:15px">Toutes les fiches du lot ${id} →</a></div></details></div></section>`;}).join('')}</div>${footer()}`;}
function sources(){return`${heading('Traçabilité / Sources','Des origines inspectables.','Code, schémas et documentation sont distingués. Aucun SHA ni hash de contenu n’est inventé pour transformer ces lectures en snapshot reproductible.',`<button class="btn" data-export="sources">Manifeste ${icon('download')}</button>`)}<div class="notice amber"><strong>État actuel : sources non figées.</strong> Les fichiers <code>main</code> peuvent correspondre à des révisions différentes. Le script de collecte fourni permet de produire un nouveau snapshot cohérent par dépôt ; il n’a pas été exécuté avec succès ici.</div><div class="steps"><div class="step"><div class="eyebrow">${D.sources.filter(s=>s.status==='inspected').length} sources</div><h3>Inspectées</h3><p>Le code ou la documentation a été consulté. Cela ne vaut pas test backend.</p></div><div class="step"><div class="eyebrow">${D.sources.filter(s=>s.status==='prior_audit').length} sources</div><h3>Audit antérieur</h3><p>Référence issue du relevé précédent, à recontrôler au SHA retenu.</p></div><div class="step"><div class="eyebrow">${D.sources.filter(s=>s.status==='to_inspect').length} source(s)</div><h3>À inspecter</h3><p>Piste identifiée sans validation du comportement dans cette livraison.</p></div></div><div class="filterbar"><input id="source-search" class="field" placeholder="Rechercher une source, un chemin, un dépôt…" aria-label="Rechercher une source"></div><div class="source-grid" id="source-grid">${sourceCards(D.sources)}</div><div class="detail-section"><h2>Produire un vrai snapshot</h2>${codebox('Collecte publique reproductible','python scripts/fetch_snapshot.py --out snapshot\nnode scripts/extract_schema.js snapshot/openapi.json --out data/openapi-inventory.json','Shell')}<p class="small muted" style="margin-top:12px">La collecte nécessite un accès réseau. Chaque succès conserve l’URL au SHA, la taille et le SHA-256 des bytes ; chaque échec reste dans le manifeste. L’extraction structurelle n’établit pas la compatibilité Codex.</p></div>${footer()}`;}
function sourceCards(sources){return sources.map(s=>`<section class="card source-card" id="source-${s.id}"><div class="tags">${pill(s.kind)}${pill(s.status==='inspected'?'Inspectée':s.status==='prior_audit'?'Audit antérieur':'À inspecter',s.status==='inspected'?'green':'amber')}</div><h3>${esc(s.title)}</h3><div class="path">${esc(s.repo||'Documentation officielle')}<br>${esc(s.path||s.url)}</div><p>${esc(s.note)}</p><div class="source-meta"><span>Consultation : ${esc(s.retrievedAt)}</span><span>SHA : non figé</span><span>Hash bytes : absent</span></div><div class="source-links">${sourceLink(s.id,'Ouvrir la source')}<a href="#explore/all?q=${encodeURIComponent(s.path||s.title)}">Trouver les fiches →</a></div></section>`).join('');}
function experiments(){return`${heading('Validation / Ce qui reste à prouver','Transformer un candidat en contrat.','Les scénarios ci-dessous définissent les tests à réaliser. Ce site n’a effectué aucune requête authentifiée et ne modifie aucun compte.')}<div class="stats"><div class="stat"><div class="stat-number">${D.experiments.length}</div><div class="stat-label">Expériences proposées</div></div><div class="stat"><div class="stat-number">0</div><div class="stat-label">Tests backend exécutés</div></div><div class="stat"><div class="stat-number">${E.filter(e=>e.mapping==='unknown').length}</div><div class="stat-label">Mappings non établis</div></div><div class="stat"><div class="stat-number">—</div><div class="stat-label">Taux de compatibilité inconnu</div></div></div><div class="grid-2">${D.experiments.map(x=>`<div class="card"><div class="tags">${pill(x.id)}${pill('Lot '+x.lot)}${pill('Non exécuté','amber')}</div><h3 style="margin-top:13px">${esc(x.title)}</h3><p>${esc(x.procedure)}</p><p class="small"><strong>Pourquoi :</strong> ${esc(x.reason)}</p></div>`).join('')}</div><div class="section-head"><h2>Limites de cette livraison</h2></div><div class="card">${D.meta.limitations.map(n=>`<div class="note-line">${icon('info')}<span>${esc(n)}</span></div>`).join('')}<div class="note-line">${icon('info')}<span>Les tests de l’outil de documentation sont séparés des tests du backend. Voir <code>tests/unit-results.txt</code> et <code>tests/ui-results.json</code> dans l’archive pour les vérifications effectivement réalisées.</span></div></div><div class="section-head"><h2>Règle de publication d’une capacité</h2></div>${codebox('Proposition de registre de validation',JSON.stringify({feature_id:'<fiche>',provider_identity:'<identité non secrète>',model_id:'<catalogue du compte>',client_version:'<version exacte>',source_snapshot:'<SHAs>',transport:'HTTP | SSE | WS | WebRTC',tested_at:null,status:'NOT_RUN',request_fixture_sha256:null,observed_events:[],known_losses:[],evidence:[]},null,2))}<div class="notice" style="margin-top:15px">Les captures doivent être <strong>expurgées des credentials, cookies, liens signés et contenu privé</strong> avant archivage. Ne pas inscrire de secrets dans ce registre ou dans les exports du site.</div>${footer()}`;}
const DEMO={"openapi": "3.1.0", "info": {"title": "Fixture pédagogique — pas le contrat OpenAI officiel", "version": "1.0"}, "servers": [{"url": "https://example.invalid/v1"}], "paths": {"/responses": {"post": {"operationId": "fixtureCreateResponse", "requestBody": {"content": {"application/json": {"schema": {"$ref": "#/components/schemas/FixtureRequest"}}}}, "responses": {"200": {"content": {"application/json": {"schema": {"$ref": "#/components/schemas/FixtureResponse"}}}}}}}}, "components": {"schemas": {"Base": {"type": "object", "properties": {"model": {"type": "string"}, "nullableIntersection": {"type": ["integer", "null"]}}, "required": ["model"]}, "FixtureRequest": {"allOf": [{"$ref": "#/components/schemas/Base"}, {"type": "object", "properties": {"nullableIntersection": {"type": "integer", "minimum": 0}, "input": {"oneOf": [{"type": "string"}, {"type": "array", "items": {"$ref": "#/components/schemas/Message"}}]}, "stream": {"type": "boolean", "default": false}}, "required": ["input"]}]}, "Message": {"type": "object", "properties": {"role": {"enum": ["user", "assistant"]}, "content": {"type": "string"}, "parent": {"$ref": "#/components/schemas/Message"}}, "required": ["role", "content"]}, "FixtureResponse": {"type": "object", "properties": {"id": {"type": "string"}, "output": {"type": "array", "items": {"$ref": "#/components/schemas/Message"}}}, "required": ["id"]}}}};
function schemas(){return`${heading('Outils / Schémas & diffs','Suivre le schéma, pas deviner le type.','Importer un document OpenAPI JSON pour inspecter ses routes, références et champs imbriqués. Le résolveur conserve les intersections et les variantes sans écraser leurs contraintes.')}<div class="notice"><strong>Deux données différentes :</strong> les fiches de mapping sont une projection d’audit. Le document OpenAPI complet n’est pas embarqué. L’import travaille sur vos bytes locaux ; rien n’est envoyé à un serveur.</div><div class="schema-controls"><button class="btn primary" data-action="import-schema">Importer OpenAPI JSON ${icon('download')}</button><button class="btn" data-action="load-demo">Essayer la fixture pédagogique</button><button class="btn" data-action="import-diff" ${!state.schemaDoc?'disabled':''}>Comparer une autre version</button></div><input type="file" accept=".json,application/json" id="schema-file" class="hidden"><input type="file" accept=".json,application/json" id="schema-diff-file" class="hidden"><div id="schema-lab">${schemaLab()}</div><div class="section-head"><h2>Ce que fait le résolveur</h2></div><div class="grid-3"><div class="card"><h3><code>$ref</code> traçable</h3><p>Résolution des JSON Pointers locaux, avec chemin d’origine. Les cycles sont arrêtés et signalés ; les références externes ne sont pas récupérées silencieusement.</p></div><div class="card"><h3><code>allOf</code> = conjonction</h3><p>Les contraintes restent toutes présentes. Les noms de propriétés requises sont réunis ; une contrainte incompatible n’est jamais remplacée par la dernière.</p></div><div class="card"><h3>Branches préservées</h3><p><code>oneOf</code> et <code>anyOf</code> conservent leur contexte. La colonne « requis » se lit dans cette branche, pas comme une obligation universelle.</p></div></div><div class="notice" style="margin-top:17px">Cet outil explore des schémas ; ce n’est <strong>pas un validateur JSON Schema complet</strong>. Les limites de profondeur, cycles et références non locales sont explicites. <code>$id</code>, ancres et références dynamiques nécessitent un résolveur complet pour certifier la validation.</div>${footer()}`;}
function schemaLab(){if(!state.schemaDoc)return`<div class="dropzone" role="button" tabindex="0" data-action="import-schema">${icon('schemas')}<h3>Un vrai schéma, des origines vérifiables</h3><p>Choisir un fichier OpenAPI JSON · maximum 25 Mo<br>YAML : convertir d’abord avec le script de collecte fourni.</p></div><div class="section-head"><h2>Projection déjà documentée</h2><a class="link small" href="#explore/parameter?family=Responses">Voir les paramètres Responses →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Champ</th><th>Origine publique</th><th>Codex</th></tr></thead><tbody>${E.filter(e=>e.id.startsWith('p-response-')).slice(0,9).map(e=>`<tr data-entry="${esc(e.id)}"><td><a href="#entry/${encodeURIComponent(e.id)}" class="name">${esc(e.name)}</a></td><td><span class="small mono muted">${esc(e.openai?.pointer||'Non résolu')}</span></td><td>${badge(e.mapping)}</td></tr>`).join('')}</tbody></table></div>`;
 const doc=state.schemaDoc;let ops=[];try{ops=AtlasSchema.operations(doc);}catch(e){return`<div class="notice amber">${esc(e.message)}</div>`;}const choices=[];for(const o of ops)for(const s of o.schemas)choices.push([s.pointer,`${o.method} ${o.path} · ${s.kind==='request'?'requête':s.status} · ${s.media}`]);for(const n of Object.keys(doc.components?.schemas||{}))choices.push(['#/components/schemas/'+AtlasSchema.escapePointer(n),'Schéma · '+n]);if(!state.schemaPointer)state.schemaPointer=choices[0]?.[0]||'#';
 return`<div class="schema-imported">${icon('check')}<div><strong>${esc(state.schemaName)}</strong><br><span class="small">${ops.length} opérations hors Files / Uploads / Vidéo · ${Object.keys(doc.components?.schemas||{}).length} schémas · ${esc(doc.openapi||doc.$schema||'Version non déclarée')}</span></div></div><div class="schema-controls"><select id="schema-select" class="field" aria-label="Sélectionner un schéma">${choices.map(([p,n])=>`<option value="${esc(p)}" ${p===state.schemaPointer?'selected':''}>${esc(n)}</option>`).join('')}</select><input id="schema-pointer" class="field mono" value="${esc(state.schemaPointer)}" aria-label="JSON Pointer du schéma"><button class="btn" data-action="resolve-schema">Résoudre ${icon('arrow')}</button></div><div class="tabs"><button class="tab ${state.schemaTab==='raw'?'active':''}" data-schema-tab="raw">Brut importé</button><button class="tab ${state.schemaTab==='resolved'?'active':''}" data-schema-tab="resolved">Résolu</button><button class="tab ${state.schemaTab==='fields'?'active':''}" data-schema-tab="fields">Champs imbriqués</button><button class="tab ${state.schemaTab==='trace'?'active':''}" data-schema-tab="trace">Origines & limites</button><button class="tab ${state.schemaTab==='diff'?'active':''}" data-schema-tab="diff">Diff de versions</button><button class="tab" data-export="schema">Exporter la sélection</button></div><div id="schema-output"></div>`;
}
function resolveSchema(){if(!state.schemaDoc)return;const cmp=$('[data-action="import-diff"]');if(cmp)cmp.disabled=false;state.schemaResult=null;try{const pointer=state.schemaPointer;const r=AtlasSchema.resolve(state.schemaDoc,pointer);const inv=AtlasSchema.propertyInventory(state.schemaDoc,pointer);state.schemaResult={...r,inventory:inv,raw:AtlasSchema.get(state.schemaDoc,pointer)};renderSchemaOutput();}catch(e){$('#schema-output').innerHTML=`<div class="notice amber">${esc(e.message)}</div>`;}}
function renderSchemaOutput(){const r=state.schemaResult;if(!r||!$('#schema-output'))return;let html='';if(state.schemaTab==='raw')html=codebox('Bytes JSON parsés · sélection importée',JSON.stringify(r.raw,null,2));if(state.schemaTab==='resolved')html=codebox('Références développées · contraintes conservées',JSON.stringify(r.schema,null,2));if(state.schemaTab==='fields')html=`<div class="results-meta"><span>${r.inventory.rows.length} déclarations de propriétés ; les branches restent distinctes.</span><span>${r.inventory.issues.length} limite(s)</span></div><div class="schema-tree table-wrap"><table class="data-table"><thead><tr><th>Chemin</th><th>Type</th><th>Requis</th><th>Branche / origine</th></tr></thead><tbody>${r.inventory.rows.map(row=>`<tr><td class="mono">${esc(row.path)}</td><td>${esc(row.type)}</td><td>${row.required?'Oui':'Non'}${row.conditional?' · conditionnel':''}</td><td class="mono">${esc(row.branches.map(b=>b.operator+(b.index===undefined?'':'['+b.index+']')).join(' / '))}<br><span class="muted">${esc(row.pointer)}</span></td></tr>`).join('')}</tbody></table></div>`;if(state.schemaTab==='trace')html=`<div class="notice">${r.trace.length} référence(s) suivie(s), ${r.cycles.length} cycle(s), ${r.unresolved.length} référence(s) non résolue(s). ${r.inventory.issues.length} limite(s) dans l’inventaire. Les cycles peuvent être légitimes.</div><div style="margin-top:15px">${codebox('Rapport du résolveur',JSON.stringify({trace:r.trace,cycles:r.cycles,unresolved:r.unresolved,inventoryIssues:r.inventory.issues},null,2))}</div>`;if(state.schemaTab==='diff'){if(!state.schemaBefore)html=`<div class="notice">Importer une autre version avec « Comparer une autre version ». La comparaison développe les références au même pointeur ; elle décrit une différence structurelle, pas un verdict de compatibilité.</div>`;else{let prev;try{prev=AtlasSchema.resolve(state.schemaBefore.doc,state.schemaPointer).schema;}catch(_){}const changes=AtlasSchema.diff(r.schema,prev);html=`<div class="notice"><strong>${changes.length} différence(s)</strong> · ${esc(state.schemaName)} → ${esc(state.schemaBefore.name)}. Pointeur comparé : <code>${esc(state.schemaPointer)}</code></div><div style="margin-top:15px">${codebox('Diff résolu — pas un verdict de compatibilité',JSON.stringify(changes,null,2))}</div>`;}}$('#schema-output').innerHTML=html;}
function render(){let hash=location.hash.slice(1)||'overview';const [path,query='']=hash.split('?'),parts=path.split('/');state.route=parts[0];const params=new URLSearchParams(query);let content;const main=$('#main');if(parts[0]==='explore'){state.category=parts[1]==='all'?null:parts[1];resetFilters();for(const k of ['family','mapping','location','lot'])if(params.has(k))state[k]=params.get(k);if(params.has('q'))state.query=params.get('q');content=explorer();}else if(parts[0]==='entry'){state.detailTab='mapping';content=entry(decodeURIComponent(parts.slice(1).join('/')));}else content=({overview,architecture,roadmap,sources,experiments,schemas}[parts[0]]||overview)();main.innerHTML=`<div class="page">${content}</div>`;const active=parts[0]==='explore'?parts[1]:parts[0]==='entry'?state.currentEntry?.category:parts[0];$$('.nav-link[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active));$('#breadcrumb').innerHTML=`Documentation <span>/ ${esc(LABELS[active]||'Contrats')}</span>`;document.title=(LABELS[active]||state.currentEntry?.name||'Documentation')+' — Codex Contract Atlas';closeMenu();window.scrollTo({top:0});if(state.route==='explore')renderResults();if(state.route==='schemas'&&state.schemaDoc)resolveSchema();if(parts[0]==='roadmap'&&parts[1])setTimeout(()=>{const el=document.getElementById(parts[1]);if(el)window.scrollTo({top:el.getBoundingClientRect().top+scrollY-90,behavior:'smooth'});},30);}
let volatileTheme='system';function getTheme(){try{return localStorage.getItem('atlas-theme')||volatileTheme;}catch(_){return volatileTheme;}}
function applyTheme(mode){volatileTheme=mode;const dark=mode==='dark'||(mode==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('atlas-theme',mode);}catch(_){}$('#theme-btn').innerHTML=icon(mode==='system'?'system':dark?'moon':'sun')+`<span>${{system:'Système',light:'Clair',dark:'Sombre'}[mode]}</span>`;$('#theme-btn').title='Thème : '+mode+' (cliquer pour changer)';}
function toast(msg){$('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),3500);}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Export préparé : '+name);}
function csv(rows){const columns=['id','category','family','name','mapping','executionLocation','transport','lot','confidence','liveVerified','openai','codex','notes','transformation'];const safe=v=>{let s=Array.isArray(v)?v.join(' | '):v&&typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"';};return'\uFEFF'+columns.join(',')+'\n'+rows.map(r=>columns.map(c=>safe(r[c])).join(',')).join('\n');}
function exportData(which){if(which==='json')download('codex-contract-mapping.json',JSON.stringify(D,null,2));if(which==='filtered-json')download('atlas-selection.json',JSON.stringify({meta:D.meta,filters:{category:state.category,query:state.query,family:state.family,mapping:state.mapping,location:state.location,lot:state.lot},entries:filtered()},null,2));if(which==='filtered-csv')download('atlas-selection.csv',csv(filtered()),'text/csv;charset=utf-8');if(which==='sources')download('atlas-sources.json',JSON.stringify(D.sources,null,2));if(which==='entry')download(state.currentEntry.id+'.json',JSON.stringify(state.currentEntry,null,2));if(which==='schema'&&state.schemaResult)download('schema-inspection.json',JSON.stringify({document:state.schemaName,pointer:state.schemaPointer,...state.schemaResult},null,2));}
function closeMenu(){$('#sidebar').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');}
function openSearch(){if($('#search-modal'))return;const el=document.createElement('div');el.id='search-modal';el.className='modal-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Recherche globale"><div class="modal-top">${icon('search')}<input id="global-query" placeholder="Endpoint, champ, protocole, capacité…" aria-label="Recherche globale"><button data-action="close-search">Échap</button></div><div id="global-results" class="search-results"></div><div class="modal-foot">Recherche dans ${E.length} fiches · ↑ ↓ pour naviguer · Entrée pour ouvrir</div></section>`;document.body.append(el);$('#global-query').focus();globalResults('');}
function globalResults(q){const n=norm(q),rows=(q?E.filter(e=>searchText(e).includes(n)):E.filter(e=>e.category==='endpoint')).slice(0,20);$('#global-results').innerHTML=rows.length?rows.map(e=>`<a class="search-result" href="#entry/${encodeURIComponent(e.id)}">${icon(e.category)}<div><h4>${esc(e.name)}</h4><p>${esc(e.family)} / ${LABELS[e.category]} / Lot ${e.lot}</p></div>${badge(e.mapping)}</a>`).join(''):`<div class="empty">Aucun contrat trouvé.</div>`;}
function closeSearch(){$('#search-modal')?.remove();}
async function importFile(file,comparison=false){if(!file)return;if(file.size>25*1024*1024){toast('Fichier trop volumineux : maximum 25 Mo.');return;}try{const doc=JSON.parse(await file.text());if(!doc||typeof doc!=='object'||Array.isArray(doc))throw new Error('Un objet JSON est requis.');if(comparison){state.schemaBefore={doc,name:file.name};state.schemaTab='diff';}else{state.schemaDoc=doc;state.schemaName=file.name;state.schemaPointer='';state.schemaBefore=null;state.schemaTab='raw';}$('#schema-lab').innerHTML=schemaLab();resolveSchema();toast(comparison?'Version de comparaison importée.':'Schéma importé localement.');}catch(e){toast('Import impossible : '+e.message);}}
document.addEventListener('click',async ev=>{const a=ev.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('#')){closeSearch();if(a.getAttribute('href')===location.hash&&location.hash.startsWith('#roadmap/'))render();}
 const b=ev.target.closest('[data-action],[data-export],[data-copy],[data-page],[data-entry],[data-detail-tab],[data-schema-tab],#theme-btn,#menu-btn,.mobile-scrim');if(!b)return;if(b.id==='theme-btn'){const order=['system','light','dark'];applyTheme(order[(order.indexOf(getTheme())+1)%3]);}if(b.id==='menu-btn'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));}if(b.classList.contains('mobile-scrim'))closeMenu();if(b.dataset.export)exportData(b.dataset.export);if(b.dataset.copy){const text=document.getElementById(b.dataset.copy)?.textContent||'';try{await navigator.clipboard.writeText(text);toast('Copié.');}catch(_){const ta=document.createElement('textarea');ta.value=text;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();toast('Copié.');}}
 if(b.dataset.entry&&!a)location.hash='entry/'+encodeURIComponent(b.dataset.entry);if(b.dataset.page){state.page=+b.dataset.page;renderResults();$('#results').scrollIntoView({block:'start',behavior:'smooth'});}if(b.dataset.detailTab){state.detailTab=b.dataset.detailTab;$$('[data-detail-tab]').forEach(t=>t.classList.toggle('active',t.dataset.detailTab===state.detailTab));$('#entry-content').innerHTML=entryBody(state.currentEntry);}if(b.dataset.schemaTab){state.schemaTab=b.dataset.schemaTab;$$('[data-schema-tab]').forEach(t=>t.classList.toggle('active',t.dataset.schemaTab===state.schemaTab));renderSchemaOutput();}
 switch(b.dataset.action){case'search':openSearch();break;case'close-search':closeSearch();break;case'reset-filters':resetFilters();$('#main .page').innerHTML=explorer();renderResults();break;case'copy-entry-link':try{await navigator.clipboard.writeText(location.href);toast('Lien copié.');}catch(_){toast('Référence : #entry/'+state.currentEntry.id);}break;case'import-schema':$('#schema-file').click();break;case'import-diff':$('#schema-diff-file').click();break;case'load-demo':state.schemaDoc=JSON.parse(JSON.stringify(DEMO));state.schemaName='Fixture pédagogique — non officielle';state.schemaPointer='';state.schemaBefore=null;state.schemaTab='raw';$('#schema-lab').innerHTML=schemaLab();resolveSchema();break;case'resolve-schema':state.schemaPointer=$('#schema-pointer').value.trim();resolveSchema();break;}
});
document.addEventListener('input',ev=>{if(ev.target.id==='filter-query'){state.query=ev.target.value;state.page=1;renderResults();}if(ev.target.id==='global-query')globalResults(ev.target.value);if(ev.target.id==='source-search'){const q=norm(ev.target.value);$('#source-grid').innerHTML=sourceCards(D.sources.filter(s=>norm(JSON.stringify(s)).includes(q)));}});
document.addEventListener('change',ev=>{if(ev.target.dataset.filter){state[ev.target.dataset.filter]=ev.target.value;state.page=1;renderResults();}if(ev.target.id==='schema-select'){state.schemaPointer=ev.target.value;$('#schema-pointer').value=state.schemaPointer;resolveSchema();}if(ev.target.id==='schema-file')importFile(ev.target.files[0]);if(ev.target.id==='schema-diff-file')importFile(ev.target.files[0],true);});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();openSearch();}if(ev.key==='Escape'){closeSearch();closeMenu();}if(ev.key==='Enter'&&ev.target.id==='schema-pointer'){state.schemaPointer=ev.target.value;resolveSchema();}if(ev.key==='Enter'&&ev.target.classList.contains('dropzone'))$('#schema-file').click();if($('#search-modal')){const links=$$('#global-results a'),idx=links.indexOf(document.activeElement);if(ev.key==='ArrowDown'){ev.preventDefault();links[Math.min(idx+1,links.length-1)]?.focus();}if(ev.key==='ArrowUp'){ev.preventDefault();if(idx<=0)$('#global-query').focus();else links[idx-1].focus();}if(ev.key==='Enter'&&document.activeElement.id==='global-query'){ev.preventDefault();links[0]?.click();}if(ev.key==='Tab'){const focus=$$('#search-modal input,#search-modal button,#search-modal a');if(!ev.shiftKey&&document.activeElement===focus.at(-1)){ev.preventDefault();focus[0].focus();}if(ev.shiftKey&&document.activeElement===focus[0]){ev.preventDefault();focus.at(-1).focus();}}}});
document.addEventListener('mousedown',ev=>{if(ev.target.id==='search-modal')closeSearch();});window.addEventListener('hashchange',render);matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(getTheme()==='system')applyTheme('system');});nav();applyTheme(getTheme());render();
